// ================= НАСТРОЙКИ АГЕНТСТВА =================
// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.
const config = {
  // Агентство
  company: 'Название агентства',
  about: 'Покупка, продажа и аренда квартир в Киеве',
  city: 'Киев',
  support_hours: 'пн–сб 9:00–19:00',
  contact_fallback: '+380 00 000 00 00',
  timezone: 'Europe/Kyiv',
  currency: 'USD',
  phone_country: '380',        // код страны для номеров, которые клиент пишет с 0            // валюта цен в листе Listings и бюджетов по умолчанию
  mortgage_partner: 'ипотечный брокер-партнёр агентства', // кому передаём вопросы по ипотеке

  // Google Таблица с листами Listings, Leads, Viewings, Log
  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',

  // Telegram-чат агентства: новые лиды, передачи, сводка follow-up
  team_chat_id: 'ВСТАВЬТЕ_ID_ЧАТА',

  // Риелторы. id — как в колонке agent_id листа Listings.
  // calendar_id — Google Календарь риелтора (его email или ID календаря).
  // chat_id — личный Telegram риелтора для записей на просмотр; пусто — в чат агентства.
  // areas и deal_types — по ним лид без объекта попадает к нужному риелтору.
  agents: [
    { id: 'maria', name: 'Мария', calendar_id: 'maria@example.com', chat_id: '', areas: ['Печерский', 'Голосеевский'], deal_types: ['buy'] },
    { id: 'pavel', name: 'Павел', calendar_id: 'pavel@example.com', chat_id: '', areas: ['Оболонский', 'Подольский'], deal_types: ['buy', 'rent'] },
    { id: 'dina', name: 'Дина', calendar_id: 'dina@example.com', chat_id: '', areas: [], deal_types: ['rent'] },
  ],

  // Просмотры
  viewing_minutes: 60,          // длительность просмотра
  buffer_minutes: 30,           // зазор до и после другого события риелтора
  lead_time_minutes: 120,       // не раньше, чем через столько минут от сейчас
  booking_window_days: 21,      // на сколько дней вперёд можно записаться
  offer_slots: 3,               // сколько вариантов показывать
  viewing_hours: {
    mon: ['10:00', '19:00'], tue: ['10:00', '19:00'], wed: ['10:00', '19:00'],
    thu: ['10:00', '19:00'], fri: ['10:00', '19:00'], sat: ['11:00', '16:00'], sun: null,
  },

  // Лиды
  hot_score: 70,               // от этого балла лид горячий — сигнал риелтору сразу
  follow_up_days: [1, 3, 7],   // через сколько дней тишины напоминать
  follow_up_texts: [
    'Здравствуйте! Подобрал для вас варианты — остались вопросы или посмотрим что-то вживую?',
    'Добрый день! Появились новые объекты по вашим параметрам. Подобрать?',
    'Здравствуйте! Если поиск ещё актуален — напишите, обновлю подборку. Если уже не нужно — тоже дайте знать.',
  ],

  // Ключи
  agent_token: 'ЗАМЕНИТЕ_НА_ДЛИННУЮ_СЛУЧАЙНУЮ_СТРОКУ',
  debug_token: '',

  // Ограничения
  max_message_chars: 2000,
  rate_limit_messages: 20,
  rate_limit_minutes: 10,
  daily_agent_runs: 1000,
  handoff_pause_minutes: 30,

  // Обещания, которые агент давать не может
  forbidden: [
    '(верн(ём|ем|у)|компенсиру(ем|ю)|дадим|предостав(им|лю)|сделаем)[^.!?]{0,40}(деньг|скидк|компенсац|бесплатн)',
    'гарантиру(ю|ем)',
    '(одобр(ят|ит|им)|точно дадут)[^.!?]{0,30}(ипотек|кредит)',
    '(ипотек|кредит)[^.!?]{0,30}(точно |обязательно )?(одобр(ят|ит|им)|дадут)',
    '(владелец|собственник) (уступит|скинет|согласится)',
    '(торг|скидк)[^.!?]{0,20}(точно|гарантир|обязательно)',
  ],
  canary: 'RE-48-CANARY',
};

return [{ json: { config, input: $input.first().json } }];

// Guard In: проверяет вход до модели. Решает, кто отвечает: модель, заготовка или риелтор.
